nextflow_process {

    name "Test Process RIBOCODE_METAPLOTS"
    script "../main.nf"
    process "RIBOCODE_METAPLOTS"

    tag "modules"
    tag "modules_nfcore"
    tag "ribocode"
    tag "ribocode/metaplots"

    test("test_ribocode_metaplots") {

        config "./nextflow.config"

        def annotation
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            annotation = extract(modules_testdata_base_path + 'genomics/homo_sapiens/riboseq_expression/ribocode/annotation.tar.gz').resolve('annotation')
        }

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/aligned_reads/SRX11780887.Aligned.toTranscriptome.out.bam", checkIfExists: true)
                ]
                input[1] = [ [ id:'annotation' ], file('${annotation}') ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out.config).match("config") },
                { assert process.out.pdf[0][1].toString().endsWith('.pdf') },
                { assert snapshot(process.out.findAll { key, val -> key.startsWith("versions") }).match("versions") }
            )
        }
    }

    test("test_ribocode_metaplots - stub") {

        options "-stub"
        config "./nextflow.config"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/aligned_reads/SRX11780887.Aligned.toTranscriptome.out.bam", checkIfExists: true)
                ]
                input[1] = [
                    [ id:'annotation' ],
                    file("annotation")
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.config[0][1].toString().endsWith('_config.txt') },
                { assert process.out.pdf[0][1].toString().endsWith('.pdf') }
            )
        }
    }

    test("test_ribocode_metaplots - empty config failure") {

        config "./nextflow_fail.config"

        def annotation
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            annotation = extract(modules_testdata_base_path + 'genomics/homo_sapiens/riboseq_expression/ribocode/annotation.tar.gz').resolve('annotation')
        }

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/aligned_reads/SRX11780887.Aligned.toTranscriptome.out.bam", checkIfExists: true)
                ]
                input[1] = [ [ id:'annotation' ], file('${annotation}') ]
                """
            }
        }

        then {
            assertAll(
                { assert !process.success },
                { assert process.stdout.toString().contains("ERROR: metaplots created config file with no data") }
            )
        }
    }
}
